import java.sql.*;import java.util.*;import java.nio.file.*;import java.lang.management.*;import com.alibaba.fastjson2.*;import webridge.wbridge.storedprocedure.SPConfig;import webridge.wbridge.storedprocedure.invocation.SPInvokeManager;
/** Same retained request and actual original WeBridge runtime; logging-free request timer. */
public class SnbTiming extends SnbWeBridge {
 public static void main(String[] args){try{timing(args);System.exit(0);}catch(Exception e){e.printStackTrace();System.exit(1);}}
 static void timing(String[] args)throws Exception{
  Path inputFile=Paths.get(System.getProperty("experiment.inputs")),rowsFile=Paths.get(args[0]);Files.createDirectories(rowsFile.getParent());JSONArray inputs=JSON.parseArray(new String(Files.readAllBytes(inputFile),"UTF-8"));final JSONObject x=inputs.getJSONObject(0);int warm=Integer.parseInt(args[1]),measured=Integer.parseInt(args[2]);final String[] phase={"baseline"};final boolean[] spStart={false},spEnd={false};
  SnbAccess.configure(Paths.get(System.getProperty("alignment.dir")));SnbAccess.url=System.getProperty("experiment.mysql.url",SnbAccess.url);SPConfig.addConfig(home.resolve("aligned.conf").toFile());System.setProperty("spDefDir",home.resolve("generated/sql").toString());ThreadMXBean cpu=ManagementFactory.getThreadMXBean();if(!cpu.isCurrentThreadCpuTimeSupported())throw new IllegalStateException("No current thread CPU timer");if(!cpu.isThreadCpuTimeEnabled())cpu.setThreadCpuTimeEnabled(true);
  SnbAccess.regionBoundary=new SnbAccess.RegionBoundary(){public void enter(Connection c)throws Exception{if(phase[0].equals("sp")){SPInvokeManager.beginApi(api);SPInvokeManager.setInvokingSp(true);paramBuffer(x);spStart[0]=SPInvokeManager.isInvokingSp();}}public void leave(Connection c)throws Exception{if(phase[0].equals("sp")){spEnd[0]=SPInvokeManager.isInvokingSp();SPInvokeManager.endApi();}}};
  try(Connection c=DriverManager.getConnection(SnbAccess.url,"root","")){Files.write(out.resolve("connection-id.json"),JSON.toJSONString(Collections.singletonMap("connection_id",c.getClass().getMethod("getId").invoke(c))).getBytes("UTF-8"));
   for(String next:args[3].split(",")){phase[0]=next;for(int i=0;i<warm+measured;i++){Map<String,Long> before=status(c);SnbAccess.calls=0;SnbAccess.kinds.clear();spStart[0]=false;spEnd[0]=false;Path requestMarker=out.resolve("request-active.json");JSONObject active=new JSONObject();active.put("start_mono_ns",System.nanoTime());active.put("start_wall_ms",System.currentTimeMillis());active.put("phase",next);active.put("iteration",i);active.put("warmup",i<warm);active.put("api",api);Files.write(requestMarker,active.toJSONString().getBytes("UTF-8"));long startWall=System.currentTimeMillis(),start=System.nanoTime(),cpuStart=cpu.getCurrentThreadCpuTime();JSONObject result=SnbAccess.request(c,x);long cpuEnd=cpu.getCurrentThreadCpuTime(),end=System.nanoTime();Files.deleteIfExists(requestMarker);Map<String,Long> after=status(c);parity(result,x);long questions=after.get("Questions")-before.get("Questions")-1,calls=after.get("Com_call_procedure")-before.get("Com_call_procedure");if(next.equals("baseline")&&questions!=SnbAccess.calls)throw new IllegalStateException("Actual SQL/source count mismatch");if(next.equals("sp")&&(!spStart[0]||!spEnd[0]||calls!=1||(i>=warm&&questions!=4&&!Boolean.getBoolean("experiment.allow.first.sp.metadata"))))throw new IllegalStateException("Original SP not fully active: calls="+calls+" questions="+questions+" start="+spStart[0]+" end="+spEnd[0]);JSONObject row=new JSONObject();row.put("query",x.getString("query"));row.put("variant",System.getProperty("experiment.variant"));row.put("phase",next);row.put("delay_ms",Double.valueOf(System.getProperty("experiment.delay.ms","0")));row.put("iteration",i);row.put("warmup",i<warm);row.put("ms",(end-start)/1e6);row.put("thread_cpu_ms",(cpuEnd-cpuStart)/1e6);row.put("questions",questions);row.put("call_procedure",calls);row.put("source_calls",SnbAccess.calls);row.put("source_categories",new LinkedHashMap<>(SnbAccess.kinds));row.put("sp_enabled_at_start",spStart[0]);row.put("sp_enabled_at_end",spEnd[0]);row.put("oracle_ok",true);row.put("first_sp_metadata_allowed",Boolean.getBoolean("experiment.allow.first.sp.metadata"));row.put("result",result);row.put("start_wall_ms",startWall);row.put("start_mono_ns",start);row.put("end_mono_ns",end);Files.write(rowsFile,(row.toJSONString()+"\n").getBytes("UTF-8"),StandardOpenOption.CREATE,StandardOpenOption.APPEND);}}
  }finally{SPInvokeManager.endApi();SPInvokeManager.setInvokingSp(false);}
 }
}
